const $=selector=>document.querySelector(selector);
const state={mode:localStorage.getItem("barangMode")||"light",language:localStorage.getItem("barangLanguage")||"en",authMode:"login",user:JSON.parse(localStorage.getItem("barangUser")||"null"),token:localStorage.getItem("barangToken")||"",selectedService:"",activeChatId:null,aiSessionId:null,handoff:false};
const STAFF_INACTIVITY_TIMEOUT_MS=10*60*1000;
const API_BASE=location.protocol==="file:"?"http://localhost:8000":"";
const api=async(path,options={})=>{const response=await fetch(`${API_BASE}${path}`,{...options,headers:{"Content-Type":"application/json",...(state.token?{Authorization:`Bearer ${state.token}`}:{})}});const payload=await response.json();if(!response.ok)throw new Error(payload.error||"Request failed.");return payload};
const handleApiError=error=>{if(error.message==="Please log in first."||error.message==="Staff access is required."){localStorage.removeItem("barangUser");localStorage.removeItem("barangToken");state.user=null;state.token="";showAuth()}else console.warn(error.message)};
