const resumeAiConversation=message=>{state.handoff=false;state.activeChatId=null;$("#chat-input").disabled=false;$("#escalate-chat").disabled=false;$("#escalate-chat").textContent=state.language==="fil"?"Magtanong ulit sa staff":"Ask a staff member again";$("#chat-messages").insertAdjacentHTML("beforeend",`<div class="message bot">${message}</div>`);};
const handoffHasExpired=messages=>{const lastMessage=messages.at(-1);return !lastMessage||!lastMessage.created_at||Date.now()-Date.parse(lastMessage.created_at)>=STAFF_INACTIVITY_TIMEOUT_MS};
const loadResidentChats=async()=>{try{const result=await api("/api/chats");const chat=result.chats.find(item=>item.service===state.selectedService||state.selectedService==="General inquiry");if(chat){state.activeChatId=chat.id;state.handoff=["open","answered"].includes(chat.status)&&!chat.archived;$("#chat-messages").replaceChildren(...chat.messages.map(item=>{const bubble=document.createElement("div");bubble.className=`message ${item.sender_role==="resident"?"user":"bot"}`;bubble.textContent=item.message;return bubble}));if(chat.archived){resumeAiConversation(state.language==="fil"?"Na-archive ng staff ang usapan. Maaari kang magpatuloy sa Barang-AI o humingi ulit ng tulong sa staff.":"This conversation was archived by staff. You can continue with Barang-AI or ask a staff member again.");}else if(state.handoff&&handoffHasExpired(chat.messages)){resumeAiConversation(state.language==="fil"?"Wala nang bagong mensahe mula sa staff sa loob ng 10 minuto. Maaari kang magtanong muli sa Barang-AI o humingi ulit ng tulong sa staff.":"There have been no new messages from staff for 10 minutes. You can continue with Barang-AI or ask a staff member again.");}else if(state.handoff){$("#escalate-chat").disabled=true;$("#escalate-chat").textContent=state.language==="fil"?"Nakakonekta sa staff":"Connected to staff"}}}catch(error){handleApiError(error)}};
const refreshActiveConversation=async()=>{if(!state.activeChatId||$("#chat-panel").classList.contains("hidden"))return;try{const result=await api(`/api/chats/${state.activeChatId}/messages`);if(result.chat?.archived){resumeAiConversation(state.language==="fil"?"Na-archive ng staff ang usapan. Maaari kang magpatuloy sa Barang-AI o humingi ulit ng tulong sa staff.":"This conversation was archived by staff. You can continue with Barang-AI or ask a staff member again.");return}if(state.handoff&&handoffHasExpired(result.messages)){resumeAiConversation(state.language==="fil"?"Wala nang bagong mensahe mula sa staff sa loob ng 10 minuto. Maaari kang magtanong muli sa Barang-AI o humingi ulit ng tulong sa staff.":"There have been no new messages from staff for 10 minutes. You can continue with Barang-AI or ask a staff member again.");return}const messages=$("#chat-messages");const existingMessages=Array.from(messages.children).map(element=>element.textContent);const newMessages=state.handoff?result.messages.filter(item=>item.sender_role==="staff"&&!existingMessages.includes(item.message)):result.messages;newMessages.forEach(item=>{const bubble=document.createElement("div");bubble.className=`message ${item.sender_role==="resident"?"user":"bot"}`;bubble.textContent=item.message;messages.appendChild(bubble)});if(newMessages.length)messages.scrollTop=messages.scrollHeight}catch(error){handleApiError(error)}};
document.addEventListener("click",async event=>{const archiveButton=event.target.closest("[data-archive-chat-id]");if(archiveButton){const archived=archiveButton.dataset.archived==="true";if(!archived&&!confirm(text("confirmArchive")))return;try{await api(`/api/chats/${archiveButton.dataset.archiveChatId}`,{method:"PATCH",body:JSON.stringify({archived:!archived})});await refreshStaffInbox()}catch(error){handleApiError(error)}return}const deleteButton=event.target.closest("[data-delete-chat-id]");if(deleteButton){if(!confirm(text("confirmRemove")))return;try{await api(`/api/chats/${deleteButton.dataset.deleteChatId}`,{method:"DELETE"});if($("#staff-reply-form").dataset.chatId===deleteButton.dataset.deleteChatId){$("#staff-reply-modal").classList.add("hidden");$("#staff-reply-form").dataset.chatId=""}await refreshStaffInbox()}catch(error){handleApiError(error)}return}const replyButton=event.target.closest("[data-chat-id]");if(replyButton){$("#staff-reply-modal").classList.remove("hidden");$("#staff-reply-form").dataset.chatId=replyButton.dataset.chatId;$("#reply-resident-name").textContent=replyButton.dataset.chatName;const messages=JSON.parse(replyButton.dataset.chatMessages||"[]");$("#staff-chat-messages").replaceChildren(...messages.map(item=>{const bubble=document.createElement("div");bubble.className=`message ${item.sender_role==="resident"?"bot":"user"}`;bubble.textContent=item.message;return bubble}));$("#staff-reply-text").focus();return}const transactionStatus=event.target.closest("[data-update-status-id]");if(transactionStatus){const nextStatus=transactionStatus.value;try{await api(`/api/transactions/${transactionStatus.dataset.updateStatusId}/status`,{method:"POST",body:JSON.stringify({status:nextStatus})});await refreshStaffInbox()}catch(error){handleApiError(error)}return}const deleteTransaction=event.target.closest("[data-delete-transaction-id]");if(deleteTransaction){if(!confirm("Delete this transaction permanently?"))return;deleteTransaction.disabled=true;const card=deleteTransaction.closest(".transaction-card");try{await api(`/api/transactions/${deleteTransaction.dataset.deleteTransactionId}/delete`,{method:"POST"});card?.remove();await refreshStaffInbox()}catch(error){deleteTransaction.disabled=false;handleApiError(error)}return}const archiveTransaction=event.target.closest("[data-archive-transaction-id]");if(archiveTransaction){const archived=archiveTransaction.dataset.archived==="true";try{await api(`/api/transactions/${archiveTransaction.dataset.archiveTransactionId}/archive`,{method:"POST",body:JSON.stringify({archived:!archived})});await refreshStaffInbox()}catch(error){handleApiError(error)}return}});
