document.addEventListener("change",async event=>{
  const select=event.target.closest("[data-update-status-id]");
  if(!select||select.dataset.saving==="true")return;
  select.dataset.saving="true";
  select.disabled=true;
  try{
    await api(`/api/transactions/${select.dataset.updateStatusId}/status`,{method:"POST",body:JSON.stringify({status:select.value})});
    await refreshStaffInbox();
  }catch(error){handleApiError(error)}finally{select.disabled=false;delete select.dataset.saving}
});
